    statutoryQuote: "„Kdo úmyslně zničí, poškodí nebo učiní neupotřebitelnou značku a) geodetického bodu základní geodynamické sítě, b) geodetického bodu referenční sítě nultého řádu, c) geodetického bodu referenční sítě doplněného nultého řádu, d) základního nivelačního geodetického bodu, nebo e) absolutního tíhového geodetického bodu, bude potrestán odnětím svobody až na dvě léta.“",
